export const SECTIONS=[{"id":"journey","name":"The Journey","color":"gold","desc":"Start here. Meet Jesus, understand the gospel, and walk through God's whole story from Genesis to Revelation.","units":[{"t":"Meet Jesus","d":"Who Jesus is, straight from the Gospel of John.","lessons":[{"id":"journey-0-0","t":"The Word Became Flesh","teach":["John opens his Gospel at the very beginning. Before anything was created, the Word already existed, and the Word was God.","That Word is Jesus. God the Son took on human flesh and lived among us, so we could see God's glory up close."],"v":["John 1:1","John 1:14"],"q":[["Who is \"the Word\" in John 1?","Jesus","Moses","The Ten Commandments","An angel"],["What does it mean that the Word \"became flesh\"?","God the Son became a real human being","Jesus stopped being God","God wrote a book","An angel appeared as a man"]]},{"id":"journey-0-1","t":"The Lamb of God","teach":["When John the Baptist saw Jesus coming, he pointed and called Him the Lamb of God.","In the Old Testament, lambs were sacrificed for sin. Jesus is the perfect Lamb who takes away the sin of the world, once and for all."],"v":["John 1:29"],"q":[["What did John the Baptist call Jesus?","The Lamb of God","The Lion of Judah","The Son of David","The Great Prophet"],["What does the Lamb of God take away?","The sin of the world","The law of Moses","Sickness only","The temple"]]},{"id":"journey-0-2","t":"Born Again","teach":["A religious leader named Nicodemus came to Jesus at night. Jesus told him that no one can see the kingdom of God unless he is born again.","New life comes from God, not from our own effort. John 3:16 explains how: God loved the world so much that He gave His Son."],"v":["John 3:3","John 3:16"],"q":[["Who came to Jesus at night?","Nicodemus","Peter","Pilate","Zacchaeus"],["According to John 3:16, what do those who believe receive?","Eternal life","Riches","A long life on earth","A new name"]]},{"id":"journey-0-3","t":"The Way, the Truth, the Life","teach":["Jesus did not say He knows the way. He said He IS the way. No one comes to the Father except through Him.","He is also the resurrection and the life. Everyone who believes in Him will live, even though they die."],"v":["John 14:6","John 11:25"],"q":[["How does a person come to the Father?","Through Jesus","By being a good person","Through any religion","By keeping the law perfectly"],["Jesus said, \"I am the resurrection and the ___.\"","life","light","truth","door"]]}]},{"t":"The Good News","d":"Why we need a Savior and how God saves us.","lessons":[{"id":"journey-1-0","t":"All Have Sinned","teach":["Sin is falling short of God's perfect standard, and every single person has done it.","Isaiah describes us like sheep that have wandered off, each going our own way. But even there, God had a plan: He laid our sin on His Servant."],"v":["Romans 3:23","Isaiah 53:6"],"q":[["Who has sinned, according to Romans 3:23?","All people","Only bad people","Only those without the law","No one who goes to church"],["Isaiah compares us to wandering ___.","sheep","goats","birds","children"]]},{"id":"journey-1-1","t":"The Gift of God","teach":["A wage is something you earn. The wage sin earns is death.","But eternal life is not a wage. It is a free gift from God, given in Christ Jesus our Lord."],"v":["Romans 6:23"],"q":[["What are the wages of sin?","Death","Sadness","Poverty","Bad luck"],["How do we receive eternal life?","As a free gift in Christ Jesus","By earning it","By paying for it","By being born into a good family"]]},{"id":"journey-1-2","t":"While We Were Still Sinners","teach":["God did not wait for us to clean ourselves up.","Christ died for us while we were still sinners. That is how God proves His love for us."],"v":["Romans 5:8"],"q":[["When did Christ die for us?","While we were still sinners","After we became good","After we asked Him","Only after we were baptized"],["What does Romans 5:8 say Christ's death proves?","God's love for us","God's anger","That we are good enough","That the law is gone"]]},{"id":"journey-1-3","t":"Saved by Grace","teach":["Grace means a gift we could never deserve. We are saved by grace, through faith.","Salvation is not from ourselves and not by works, so no one can boast. It is all God's gift."],"v":["Ephesians 2:8-9"],"q":[["We are saved by grace through ___.","faith","works","good deeds","church attendance"],["Why is salvation not by works?","So that no one can boast","Because works do not matter to God","Because only priests can work","Because it is earned later"]]},{"id":"journey-1-4","t":"Confess and Believe","teach":["How does someone receive this gift? Confess with your mouth that Jesus is Lord, and believe in your heart that God raised Him from the dead.","God's promise is wide open: everyone who calls on the name of the Lord will be saved."],"v":["Romans 10:9","Romans 10:13"],"q":[["What do we confess with our mouth?","Jesus is Lord","I am a good person","The Ten Commandments","Nothing"],["Who will be saved, according to Romans 10:13?","Everyone who calls on the name of the Lord","Only Israel","Only those born in a church","Only the apostles"]]}]},{"t":"In the Beginning","d":"Creation, the fall, and God's first promises.","lessons":[{"id":"journey-2-0","t":"God Created","teach":["The Bible opens with God. He created everything that exists, out of nothing, by His word.","On the sixth day He made people, male and female, in His own image. Every person carries that dignity."],"v":["Genesis 1:1","Genesis 1:27"],"q":[["Who created the heavens and the earth?","God","Adam","The angels","No one"],["In whose image were people created?","God's image","The angels' image","The animals' image","Their own image"]]},{"id":"journey-2-1","t":"The Fall and the First Promise","teach":["Adam and Eve disobeyed God and ate from the one tree He told them not to eat from. Sin and death entered the world.","Right away, God made a promise: a descendant of the woman would crush the serpent's head. This is the first promise of Jesus in the Bible."],"v":["Genesis 3:6","Genesis 3:15"],"q":[["Who tempted Eve?","The serpent","Cain","An angel","Adam"],["Genesis 3:15 is the first promise of whom?","Jesus, who defeats Satan","Moses","Noah","King David"]]},{"id":"journey-2-2","t":"Noah Found Favor","teach":["The world grew so wicked that God sent a flood. But Noah found favor in the eyes of the LORD.","God saved Noah and his family in the ark. Afterward, God set His rainbow in the clouds as the sign of His covenant."],"v":["Genesis 6:8","Genesis 9:13"],"q":[["Who found favor with the LORD?","Noah","Abraham","Cain","Lot"],["What was the sign of God's covenant after the flood?","A rainbow","A dove","A star","An altar"]]},{"id":"journey-2-3","t":"The Promise to Abraham","teach":["God called Abram to leave his home and promised to make him a great nation. Through him, all the families of the earth would be blessed.","Abram believed the LORD, and God credited it to him as righteousness. Faith has always been the way to God."],"v":["Genesis 12:2-3","Genesis 15:6"],"q":[["Through Abraham, who would be blessed?","All the families of the earth","Only his family","Only Egypt","No one"],["What did God credit to Abram as righteousness?","His faith","His wealth","His sacrifices","His age"]]}]},{"t":"God's Rescue","d":"The Exodus, the Passover, and God's law.","lessons":[{"id":"journey-3-0","t":"I AM WHO I AM","teach":["God spoke to Moses from a burning bush and sent him to free Israel from slavery in Egypt.","When Moses asked God's name, God answered, \"I AM WHO I AM.\" He is eternal and needs nothing. Jesus later used this same name for Himself."],"v":["Exodus 3:14"],"q":[["How did God speak to Moses?","From a burning bush","In a dream","Through a prophet","On a mountain of fire"],["What name did God give Moses?","I AM WHO I AM","The Most High","The Holy One","The Ancient of Days"]]},{"id":"journey-3-1","t":"The Passover","teach":["The final plague on Egypt was death of the firstborn. God told Israel to put the blood of a lamb on their doorframes.","When God saw the blood, He passed over that house. This points straight to Jesus, our Passover Lamb, whose blood saves us."],"v":["Exodus 12:13"],"q":[["What protected Israel's homes?","The blood of a lamb","A prayer","A golden sign","Their good works"],["Who is our Passover Lamb?","Jesus","Moses","Aaron","Isaac"]]},{"id":"journey-3-2","t":"The LORD Will Fight for You","teach":["Pharaoh's army chased Israel to the edge of the Red Sea. The people panicked.","Moses told them: the LORD will fight for you; you need only to be still. Then God split the sea and Israel walked through on dry ground."],"v":["Exodus 14:14"],"q":[["What did Moses tell the people at the Red Sea?","The LORD will fight for you","Run for the mountains","Go back to Egypt","Build boats"],["How did Israel cross the sea?","God parted it and they walked on dry ground","They swam","They built a bridge","They sailed"]]},{"id":"journey-3-3","t":"The Ten Commandments","teach":["At Mount Sinai, God gave His law. It begins with who He is: the God who rescued them.","The first command: you shall have no other gods before Me. God's people obey because they have already been rescued, not to earn it."],"v":["Exodus 20:2-3"],"q":[["Where were the Ten Commandments given?","Mount Sinai","Mount Carmel","Jerusalem","Bethlehem"],["What is the first commandment?","No other gods before Me","Do not steal","Honor your parents","Keep the Sabbath"]]},{"id":"journey-3-4","t":"Love the LORD Your God","teach":["This passage is called the Shema. It declares that the LORD is one.","Jesus called it the greatest commandment: love the LORD your God with all your heart, all your soul, and all your strength."],"v":["Deuteronomy 6:4-5"],"q":[["Jesus called Deuteronomy 6:5 the greatest ___.","commandment","promise","prophecy","psalm"],["How are we to love God?","With all our heart, soul, and strength","Only on the Sabbath","With half our heart","Only when things go well"]]}]},{"t":"Kings and Prophets","d":"David's throne and the promises of a coming King.","lessons":[{"id":"journey-4-0","t":"The LORD Looks at the Heart","teach":["God sent the prophet Samuel to anoint a new king. Samuel expected someone tall and impressive.","God chose David, the youngest shepherd boy, because the LORD looks at the heart. David later wrote, \"The LORD is my shepherd.\""],"v":["1 Samuel 16:7","Psalm 23:1"],"q":[["What does the LORD look at?","The heart","Appearance","Height","Wealth"],["What was David's job before he was king?","Shepherd","Fisherman","Carpenter","Priest"]]},{"id":"journey-4-1","t":"A Throne Forever","teach":["God promised David that his house and kingdom would endure forever and his throne would be established forever.","Jesus is the Son of David who fulfills that promise. His kingdom will never end."],"v":["2 Samuel 7:16"],"q":[["How long would David's throne last?","Forever","Forty years","Until the exile","Seven generations"],["Who fulfills God's promise to David?","Jesus","Solomon","Hezekiah","Saul"]]},{"id":"journey-4-2","t":"Unto Us a Child Is Born","teach":["Hundreds of years before Jesus, Isaiah announced a child who would be called Mighty God and Prince of Peace.","Micah even named the town: the ruler of Israel would come from Bethlehem. Jesus was born right there."],"v":["Isaiah 9:6","Micah 5:2"],"q":[["Which town did Micah name?","Bethlehem","Nazareth","Jerusalem","Capernaum"],["Which of these names does Isaiah 9:6 give the child?","Prince of Peace","Son of Thunder","King of Egypt","High Priest"]]},{"id":"journey-4-3","t":"The Suffering Servant","teach":["Isaiah 53 describes the Messiah's suffering in stunning detail, about 700 years before the cross.","He was despised and rejected, pierced for our transgressions, and by His stripes we are healed."],"v":["Isaiah 53:3","Isaiah 53:5"],"q":[["By His stripes we are ___.","healed","judged","forgotten","scattered"],["Isaiah 53 points to whom?","Jesus on the cross","King David","Isaiah himself","The nation of Babylon"]]}]},{"t":"The Cross and the Empty Tomb","d":"Jesus' death and resurrection.","lessons":[{"id":"journey-5-0","t":"The Last Supper","teach":["On the night He was betrayed, Jesus shared the Passover meal with His disciples.","He took bread and said, \"This is My body.\" He took the cup and called it the new covenant in His blood. Christians remember this in communion."],"v":["Luke 22:19-20"],"q":[["What did Jesus say the bread was?","His body","His word","Manna","The law"],["What did Jesus call the cup?","The new covenant in His blood","The old covenant","A cup of blessing for Israel only","A symbol of the temple"]]},{"id":"journey-5-1","t":"It Is Finished","teach":["On the cross, Jesus said, \"It is finished.\" The price for sin was paid in full.","He bore our sins in His body on the tree, so that we might die to sin and live for righteousness."],"v":["John 19:30","1 Peter 2:24"],"q":[["What were some of Jesus' last words on the cross?","It is finished","I will return","Forgive me","Save yourselves"],["Whose sins did Jesus bear on the cross?","Ours","Only His disciples'","Only the Romans'","None"]]},{"id":"journey-5-2","t":"He Is Risen","teach":["On the third day, women came to the tomb and found it empty. An angel said, \"He is not here; He has risen, just as He said!\"","Paul calls this the gospel of first importance: Christ died for our sins, was buried, and was raised on the third day."],"v":["Matthew 28:6","1 Corinthians 15:3-4"],"q":[["On what day did Jesus rise?","The third day","The seventh day","The fortieth day","The first day after Passover week"],["What did the angel say at the tomb?","He is not here; He has risen","He was taken away","Wait here for Him","He is sleeping"]]},{"id":"journey-5-3","t":"My Lord and My God","teach":["Thomas said he would not believe unless he saw Jesus' wounds. Then the risen Jesus appeared and showed him.","Thomas cried out, \"My Lord and my God!\" Jesus said those who believe without seeing are blessed. That is us."],"v":["John 20:28-29"],"q":[["What did Thomas call Jesus?","My Lord and my God","Teacher","A prophet","A ghost"],["Who did Jesus say are blessed?","Those who believe without seeing","Only those who saw Him","Only the twelve","Those who doubt"]]}]},{"t":"The Church Is Born","d":"The Great Commission, Pentecost, and the gospel spreading.","lessons":[{"id":"journey-6-0","t":"Go and Make Disciples","teach":["Before He ascended, Jesus gave His followers their mission: go and make disciples of all nations.","He promised, \"I am with you always, even to the end of the age.\" That promise is still ours."],"v":["Matthew 28:19-20"],"q":[["Who are we to make disciples of?","All nations","Only Israel","Only our family","Only the rich"],["How long did Jesus promise to be with us?","Always, to the end of the age","For forty days","Until Pentecost","Only in the temple"]]},{"id":"journey-6-1","t":"Pentecost","teach":["Fifty days after the resurrection, the Holy Spirit filled the disciples and they spoke in other languages.","Peter preached, and about 3,000 people were saved that day. He told them: repent and be baptized in the name of Jesus Christ."],"v":["Acts 2:4","Acts 2:38"],"q":[["Who filled the disciples at Pentecost?","The Holy Spirit","An angel","Moses","John the Baptist"],["What did Peter tell the crowd to do?","Repent and be baptized","Go home","Offer a sacrifice","Wait for a sign"]]},{"id":"journey-6-2","t":"The Road to Damascus","teach":["Saul hated Christians and was hunting them down. On the road to Damascus, a light from heaven flashed around him.","Jesus Himself spoke: \"Saul, Saul, why do you persecute Me?\" Saul became Paul, the greatest missionary in history."],"v":["Acts 9:4-5"],"q":[["Who spoke to Saul on the road?","Jesus","Peter","An angel","Stephen"],["What was Saul's new name?","Paul","Peter","Silas","Stephen"]]},{"id":"journey-6-3","t":"Not Ashamed","teach":["Paul was beaten, jailed, and shipwrecked for preaching Jesus, and he was never ashamed.","The gospel is the power of God for the salvation of everyone who believes."],"v":["Romans 1:16"],"q":[["Paul said he is not ashamed of what?","The gospel","His past","Rome","The law"],["The gospel is the ___ of God for salvation.","power","secret","plan B","law"]]}]},{"t":"Walking by Faith","d":"Living the Christian life every day.","lessons":[{"id":"journey-7-0","t":"Do Not Be Anxious","teach":["God invites you to bring everything to Him in prayer, with thanksgiving.","When you do, the peace of God, which surpasses all understanding, guards your heart and mind in Christ Jesus."],"v":["Philippians 4:6-7"],"q":[["What should we do instead of being anxious?","Pray with thanksgiving","Try harder","Ignore the problem","Worry quietly"],["What guards our hearts and minds?","The peace of God","Our own strength","Good luck","Other people"]]},{"id":"journey-7-1","t":"The Fruit of the Spirit","teach":["When the Holy Spirit lives in a believer, He produces fruit in their character.","Love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control. Fruit grows over time as we stay close to Him."],"v":["Galatians 5:22-23"],"q":[["Which of these is a fruit of the Spirit?","Patience","Wealth","Fame","Strength"],["Who produces this fruit in us?","The Holy Spirit","Our willpower","Our church","Our parents"]]},{"id":"journey-7-2","t":"The Armor of God","teach":["The Christian life is a real battle against the schemes of the devil.","God doesn't send us out unprotected. Be strong in the Lord and put on the full armor of God."],"v":["Ephesians 6:10-11"],"q":[["Whose schemes do we stand against?","The devil's","Our neighbors'","The government's","Our families'"],["Where does our strength come from?","The Lord","Ourselves","Our armor alone","Other believers only"]]},{"id":"journey-7-3","t":"Without Faith","teach":["Faith is the assurance of what we hope for and the certainty of what we do not see.","Without faith it is impossible to please God. He rewards those who earnestly seek Him."],"v":["Hebrews 11:1","Hebrews 11:6"],"q":[["Faith is the ___ of what we hope for.","assurance","opposite","end","price"],["God rewards those who...","Earnestly seek Him","Never ask questions","Give the most money","Are born perfect"]]},{"id":"journey-7-4","t":"A Lamp to My Feet","teach":["All Scripture is God-breathed. The Bible is God's own word to us.","It is a lamp to our feet and a light to our path, showing us the next step."],"v":["2 Timothy 3:16","Psalm 119:105"],"q":[["All Scripture is ___.","God-breathed","man-made","optional","outdated"],["Psalm 119 calls God's word a lamp to our ___.","feet","eyes","hands","house"]]}]},{"t":"Forever with God","d":"Jesus' return and the hope of heaven.","lessons":[{"id":"journey-8-0","t":"I Will Come Back","teach":["Jesus told His disciples He was going to prepare a place for them, and He would come back.","When He ascended into heaven, angels promised He would return the same way they saw Him go."],"v":["John 14:2-3","Acts 1:11"],"q":[["What is Jesus preparing for us?","A place","A test","A new law","A temple"],["How will Jesus return?","The same way He went into heaven","As a baby again","Secretly in a desert","He will not return"]]},{"id":"journey-8-1","t":"Nothing Can Separate Us","teach":["Paul lists everything that might seem powerful: death, life, angels, the present, the future.","None of it can separate us from the love of God that is in Christ Jesus our Lord."],"v":["Romans 8:38-39"],"q":[["What can separate us from God's love?","Nothing","Death","Our past","The future"],["God's love is in whom?","Christ Jesus our Lord","The angels","The law","Ourselves"]]},{"id":"journey-8-2","t":"No More Tears","teach":["The Bible ends where it began, with God making a world. This time it is a new heaven and a new earth.","God Himself will wipe away every tear. There will be no more death, mourning, crying, or pain."],"v":["Revelation 21:1","Revelation 21:4"],"q":[["What will God wipe away?","Every tear","Every memory","All the stars","The old law"],["What will there be no more of?","Death and pain","Worship","Light","People"]]},{"id":"journey-8-3","t":"Come, Lord Jesus","teach":["Jesus calls Himself the Alpha and the Omega, the First and the Last. He is the beginning and the end of the whole story.","The Bible's last promise: \"Yes, I am coming soon.\" The church answers, \"Amen. Come, Lord Jesus!\""],"v":["Revelation 22:13","Revelation 22:20"],"q":[["Alpha and Omega are the first and last letters of which alphabet?","Greek","Hebrew","Latin","English"],["What is Jesus' last promise in the Bible?","I am coming soon","I will judge you","Read this book","Build my temple"]]}]}]},{"id":"ot","name":"Old Testament","color":"ruby","desc":"From Genesis to Malachi: the Law, Israel's history, the songs of worship, and the prophets who pointed to Christ.","units":[{"t":"The Law","d":"Genesis to Deuteronomy, the five books of Moses.","lessons":[{"id":"ot-0-0","t":"It Was Very Good","teach":["God created simply by speaking: \"Let there be light,\" and there was light.","At the end of the sixth day, God looked at everything He had made, and it was very good. Creation was perfect before sin entered."],"v":["Genesis 1:3","Genesis 1:31"],"q":[["What did God create first by speaking?","Light","Animals","People","The sea"],["How did God describe all of creation on day six?","Very good","Unfinished","Broken","Ordinary"]]},{"id":"ot-0-1","t":"The LORD Will Provide","teach":["God tested Abraham by asking him to offer his son Isaac. Abraham trusted God completely.","Isaac asked where the lamb was. Abraham said God Himself would provide it. God stopped Abraham and provided a ram. Abraham named the place \"The LORD Will Provide.\""],"v":["Genesis 22:8","Genesis 22:14"],"q":[["What did Abraham say God would provide?","The lamb","Water","A new son","A sword"],["What did God provide instead of Isaac?","A ram","A dove","A goat","A calf"]]},{"id":"ot-0-2","t":"Jacob Becomes Israel","teach":["Jacob wrestled all night with a man who was God Himself, and he would not let go until he was blessed.","God gave him a new name, Israel. His twelve sons became the twelve tribes of Israel."],"v":["Genesis 32:28"],"q":[["What was Jacob's new name?","Israel","Abraham","Judah","Joseph"],["How many tribes came from Jacob's sons?","Twelve","Ten","Seven","Forty"]]},{"id":"ot-0-3","t":"God Meant It for Good","teach":["Joseph's brothers sold him into slavery. Years later God made Joseph a ruler in Egypt, and he saved many lives during a famine.","Joseph told his brothers: you intended to harm me, but God intended it for good. God works even through what others mean for evil."],"v":["Genesis 50:20"],"q":[["Who sold Joseph into slavery?","His brothers","Pharaoh","His father","The Midianites' king"],["What did God intend through Joseph's suffering?","Good, to save many lives","Punishment","Nothing","To make Joseph rich"]]},{"id":"ot-0-4","t":"Be Holy","teach":["Leviticus teaches Israel how to live as God's holy people. The reason is simple: \"Be holy, because I, the LORD your God, am holy.\"","This same chapter gives the command Jesus called the second greatest: love your neighbor as yourself."],"v":["Leviticus 19:2","Leviticus 19:18"],"q":[["Why are God's people to be holy?","Because God is holy","To be better than others","To get rich","To avoid work"],["Which famous command is in Leviticus 19:18?","Love your neighbor as yourself","Do not murder","Honor your parents","Rest on the Sabbath"]]},{"id":"ot-0-5","t":"The Priestly Blessing","teach":["God gave Aaron and the priests these exact words to bless Israel.","It is still spoken over believers today: the LORD bless you and keep you, make His face shine on you, and give you peace."],"v":["Numbers 6:24-26"],"q":[["Who first spoke this blessing over Israel?","Aaron and the priests","Moses' sister Miriam","King David","The prophets"],["What does the blessing end with?","Peace","Riches","Victory","Long life"]]}]},{"t":"History","d":"Joshua to Esther: Israel in the land.","lessons":[{"id":"ot-1-0","t":"Be Strong and Courageous","teach":["After Moses died, Joshua had to lead Israel into the promised land.","God told him: be strong and courageous, do not be afraid, for the LORD your God is with you wherever you go."],"v":["Joshua 1:9"],"q":[["Who led Israel after Moses?","Joshua","Caleb","Aaron","Gideon"],["Why could Joshua be courageous?","God was with him wherever he went","He had the biggest army","He was the tallest","The enemies were weak"]]},{"id":"ot-1-1","t":"As for Me and My House","teach":["At the end of his life, Joshua challenged Israel to choose whom they would serve.","Then he made his own choice clear: as for me and my house, we will serve the LORD."],"v":["Joshua 24:15"],"q":[["Complete it: \"As for me and my house, we will ___ the LORD.\"","serve","fear","find","praise"],["What did Joshua ask Israel to do?","Choose whom they would serve","Build a temple","Return to Egypt","Crown a king"]]},{"id":"ot-1-2","t":"Where You Go, I Will Go","teach":["Ruth was from Moab, not Israel. When her husband died, she refused to leave her mother-in-law Naomi.","She said, \"Your people will be my people, and your God will be my God.\" God honored her faith: she became the great-grandmother of King David, in the line of Jesus."],"v":["Ruth 1:16"],"q":[["Who was Ruth loyal to?","Naomi, her mother-in-law","Her sister Orpah","King Saul","Boaz's mother"],["Ruth became an ancestor of whom?","King David and Jesus","Moses","Elijah","Pharaoh"]]},{"id":"ot-1-3","t":"Speak, LORD","teach":["Young Samuel was serving in the tabernacle when he heard a voice calling his name at night.","Eli told him how to answer. Samuel said, \"Speak, for Your servant is listening.\" He grew into one of Israel's greatest prophets."],"v":["1 Samuel 3:10"],"q":[["What did Samuel say when God called?","Speak, for Your servant is listening","Who are You?","Leave me alone","I am not ready"],["Who taught Samuel how to answer?","Eli","David","Hannah","Saul"]]},{"id":"ot-1-4","t":"A Wise Heart","teach":["God told King Solomon to ask for anything. Solomon did not ask for riches or a long life.","He asked for an understanding heart to govern God's people well. God gave him wisdom, and riches and honor too."],"v":["1 Kings 3:9"],"q":[["What did Solomon ask God for?","An understanding heart","Riches","A long life","Victory over his enemies"],["Whose son was Solomon?","David's","Saul's","Samuel's","Jesse's"]]},{"id":"ot-1-5","t":"If My People","teach":["When Solomon dedicated the temple, God gave a promise for whenever His people turned away.","If they humble themselves, pray, seek His face, and turn from wickedness, He will hear, forgive, and heal their land."],"v":["2 Chronicles 7:14"],"q":[["What will God do when His people humble themselves and pray?","Hear, forgive, and heal their land","Punish them more","Ignore them","Send them away"],["When did God give this promise?","At the dedication of Solomon's temple","At the Red Sea","At Jesus' birth","At Mount Carmel"]]},{"id":"ot-1-6","t":"For Such a Time as This","teach":["A wicked official named Haman plotted to destroy all the Jews in Persia. Esther, a Jewish woman, had become queen.","Her cousin Mordecai urged her to speak up: who knows whether you have come to the kingdom for such a time as this? God placed her there on purpose."],"v":["Esther 4:14"],"q":[["Who plotted to destroy the Jews?","Haman","Pharaoh","Goliath","Nebuchadnezzar"],["Who said \"for such a time as this\"?","Mordecai","Esther","The king","Nehemiah"]]},{"id":"ot-1-7","t":"The Joy of the LORD","teach":["After the exile, Nehemiah led the people to rebuild Jerusalem's walls. Then Ezra read God's law aloud and the people wept.","Nehemiah told them not to grieve, for the joy of the LORD is your strength."],"v":["Nehemiah 8:10"],"q":[["What is our strength, according to Nehemiah 8:10?","The joy of the LORD","Our walls","Our army","Our wisdom"],["What did Nehemiah lead the people to rebuild?","Jerusalem's walls","Noah's ark","The tower of Babel","Pharaoh's palace"]]}]},{"t":"Wisdom and Worship","d":"Job, Psalms, Proverbs, and Ecclesiastes.","lessons":[{"id":"ot-2-0","t":"My Redeemer Lives","teach":["Job lost his children, his wealth, and his health, yet he would not curse God.","From the depths of his suffering came one of the boldest declarations of faith in the Bible: I know that my Redeemer lives."],"v":["Job 19:25"],"q":[["What did Job declare?","I know that my Redeemer lives","God has left me","I deserve this","I will curse God"],["What did Job lose?","His children, wealth, and health","Only his money","Only his house","Nothing"]]},{"id":"ot-2-1","t":"Through the Valley","teach":["Psalm 23 is David's song of trust in God as his shepherd.","Even in the valley of the shadow of death, he fears no evil, because God is with him. His rod and staff bring comfort."],"v":["Psalm 23:4"],"q":[["Why does David fear no evil?","Because God is with him","Because he is strong","Because the valley is safe","Because he has an army"],["What comforts David?","God's rod and staff","His sword","His crown","His friends"]]},{"id":"ot-2-2","t":"Be Still and Know","teach":["God is our refuge and strength, an ever-present help in trouble.","In the middle of chaos, God says: be still, and know that I am God. He will be exalted among the nations."],"v":["Psalm 46:1","Psalm 46:10"],"q":[["God is our refuge and ___.","strength","shelter","song","shield"],["What does God tell us to do in Psalm 46:10?","Be still and know that He is God","Run and hide","Fight harder","Count our blessings"]]},{"id":"ot-2-3","t":"A Clean Heart","teach":["David wrote Psalm 51 after the prophet Nathan confronted him about his sin with Bathsheba.","David did not make excuses. He asked God to create in him a clean heart and renew a right spirit within him. God forgives a repentant heart."],"v":["Psalm 51:10"],"q":[["What did David ask God to create in him?","A clean heart","A new kingdom","A strong army","A wise mind"],["Which prophet confronted David?","Nathan","Samuel","Elijah","Isaiah"]]},{"id":"ot-2-4","t":"The Beginning of Knowledge","teach":["Proverbs is a book of wise sayings, mostly from Solomon.","Its foundation: the fear of the LORD is the beginning of knowledge. To fear God means to honor and revere Him above all."],"v":["Proverbs 1:7"],"q":[["What is the beginning of knowledge?","The fear of the LORD","Reading many books","Age","Experience"],["Who wrote most of Proverbs?","Solomon","David","Moses","Job"]]},{"id":"ot-2-5","t":"Trust in the LORD","teach":["One of the most loved verses in the Bible.","Trust the LORD with all your heart, do not lean on your own understanding, acknowledge Him in all your ways, and He will make your paths straight."],"v":["Proverbs 3:5-6"],"q":[["What should we not lean on?","Our own understanding","God's word","His promises","Prayer"],["What will God do if we acknowledge Him?","Make our paths straight","Make us rich","Remove all problems","Give us fame"]]},{"id":"ot-2-6","t":"A Time for Everything","teach":["Ecclesiastes looks honestly at life under the sun. There is a season for everything: birth and death, weeping and laughing.","God has made everything beautiful in its time, and He has set eternity in the human heart."],"v":["Ecclesiastes 3:1","Ecclesiastes 3:11"],"q":[["What has God set in the human heart?","Eternity","Fear","Sadness","Pride"],["God has made everything ___ in its time.","beautiful","difficult","quick","equal"]]}]},{"t":"The Major Prophets","d":"Isaiah, Jeremiah, Ezekiel, and Daniel.","lessons":[{"id":"ot-3-0","t":"Holy, Holy, Holy","teach":["Isaiah saw the Lord on His throne, and angels called out, \"Holy, holy, holy is the LORD of Hosts.\"","When God asked whom He should send, Isaiah answered, \"Here am I. Send me!\""],"v":["Isaiah 6:3","Isaiah 6:8"],"q":[["What did the angels call out?","Holy, holy, holy","Glory to the King","Hallelujah","Amen, amen"],["How did Isaiah answer God's call?","Here am I. Send me!","Send someone else","I am too young","Not today"]]},{"id":"ot-3-1","t":"Immanuel","teach":["God gave a sign: a virgin would conceive and give birth to a son, and call Him Immanuel.","Immanuel means \"God with us.\" Matthew tells us this was fulfilled when Jesus was born to the virgin Mary."],"v":["Isaiah 7:14"],"q":[["What does Immanuel mean?","God with us","God saves","Prince of Peace","Son of David"],["Who fulfilled Isaiah 7:14?","Jesus, born to the virgin Mary","King Hezekiah","John the Baptist","Isaiah's son"]]},{"id":"ot-3-2","t":"Wings Like Eagles","teach":["God never grows tired or weary.","Those who wait on the LORD will renew their strength. They will soar on wings like eagles, run and not grow weary, walk and not faint."],"v":["Isaiah 40:31"],"q":[["Who will renew their strength?","Those who wait on the LORD","Those who sleep more","The young","The strong"],["They will soar on wings like ___.","eagles","doves","angels","sparrows"]]},{"id":"ot-3-3","t":"Plans for You","teach":["Jeremiah wrote to God's people in exile in Babylon. God would bring them home after seventy years.","God said He knows the plans He has for them: plans for a future and a hope. And you will find Him when you seek Him with all your heart."],"v":["Jeremiah 29:11","Jeremiah 29:13"],"q":[["Where were God's people when Jeremiah wrote this?","In exile in Babylon","In Egypt","In the wilderness","In Jerusalem's temple"],["When will we find God?","When we seek Him with all our heart","Only on holidays","Only in the temple","Never"]]},{"id":"ot-3-4","t":"A Heart of Flesh","teach":["God promised to do what the law alone could not: change hearts.","He would remove the heart of stone and give a heart of flesh, and put a new spirit within His people. This is what happens when someone is born again."],"v":["Ezekiel 36:26"],"q":[["What will God remove?","The heart of stone","The law","The temple","The land"],["What will God put within His people?","A new spirit","A new king","A new language","A new city"]]},{"id":"ot-3-5","t":"Dry Bones Live","teach":["God showed Ezekiel a valley full of dry bones and told him to prophesy to them.","As he spoke, the bones came together, got flesh, and God's breath brought them to life. Nothing is too dead for God to raise."],"v":["Ezekiel 37:4-5"],"q":[["What did Ezekiel see in the valley?","Dry bones","An army of angels","A burning bush","A golden statue"],["What brought the bones to life?","God's breath","Water","Fire","Ezekiel's strength"]]},{"id":"ot-3-6","t":"The Son of Man","teach":["Daniel saw a vision of one like a Son of Man coming with the clouds of heaven.","He was given authority, glory, and a kingdom that will never be destroyed. Jesus called Himself the Son of Man again and again."],"v":["Daniel 7:14"],"q":[["What kind of kingdom does the Son of Man receive?","One that will never be destroyed","A small kingdom","A kingdom for seventy years","Babylon"],["Who often called Himself the Son of Man?","Jesus","Daniel","Moses","Paul"]]}]},{"t":"The Minor Prophets","d":"Twelve shorter books with mighty messages.","lessons":[{"id":"ot-4-0","t":"Rend Your Hearts","teach":["Joel called Israel back to God. Tearing your clothes was a sign of grief, but God wanted more.","Tear your hearts, not your garments. Return to the LORD, for He is gracious and compassionate, slow to anger and abounding in loving devotion."],"v":["Joel 2:13"],"q":[["What does God want us to tear?","Our hearts","Our clothes","Our books","Our idols only"],["God is slow to ___.","anger","listen","help","forgive"]]},{"id":"ot-4-1","t":"Let Justice Roll","teach":["Amos was a shepherd sent to rebuke Israel for worship that was all show while the poor were mistreated.","God wanted justice to roll on like a river and righteousness like an ever-flowing stream."],"v":["Amos 5:24"],"q":[["What was Amos' job before he prophesied?","Shepherd","Priest","King","Fisherman"],["Justice should roll on like ___.","a river","the wind","a wheel","thunder"]]},{"id":"ot-4-2","t":"What the LORD Requires","teach":["People wondered what offering would please God. Micah answered simply.","God requires you to act justly, to love mercy, and to walk humbly with your God."],"v":["Micah 6:8"],"q":[["Which is NOT in Micah 6:8?","Offer a thousand rams","Act justly","Love mercy","Walk humbly with God"],["We are to walk ___ with our God.","humbly","proudly","quickly","alone"]]},{"id":"ot-4-3","t":"Salvation Is from the LORD","teach":["Jonah ran from God's call, was thrown overboard, and was swallowed by a great fish.","From inside the fish he prayed and declared, \"Salvation is from the LORD!\" God rescued him and sent him again to Nineveh."],"v":["Jonah 2:9"],"q":[["Where did Jonah pray this prayer?","Inside the great fish","In the temple","On the ship","In Nineveh"],["Where does salvation come from?","The LORD","The sailors","The king of Nineveh","Jonah"]]},{"id":"ot-4-4","t":"The Righteous Live by Faith","teach":["Habakkuk asked God hard questions about evil, and God answered: the righteous will live by faith. Paul quoted this verse to explain the gospel.","Habakkuk ended his book choosing joy: even if everything fails, I will rejoice in the LORD."],"v":["Habakkuk 2:4","Habakkuk 3:18"],"q":[["The righteous will live by ___.","faith","law","sight","strength"],["Who later quoted Habakkuk 2:4 to explain the gospel?","Paul","Moses","David","Pilate"]]},{"id":"ot-4-5","t":"He Rejoices Over You","teach":["After warning of judgment, Zephaniah ends with a beautiful picture of God's love for His people.","The LORD your God is among you; He is mighty to save. He will rejoice over you with singing."],"v":["Zephaniah 3:17"],"q":[["How does God rejoice over His people?","With singing","With silence","With anger","With a feast only"],["The LORD your God is mighty to ___.","save","judge","destroy","rest"]]},{"id":"ot-4-6","t":"Your King Is Coming","teach":["Zechariah prophesied that Jerusalem's King would come righteous and victorious, yet humble, riding on a donkey.","About 500 years later, Jesus rode into Jerusalem on a donkey on Palm Sunday, exactly as written."],"v":["Zechariah 9:9"],"q":[["What would the King ride?","A donkey","A war horse","A chariot","A camel"],["When was this fulfilled?","Jesus' entry into Jerusalem","David's coronation","The return from exile","Pentecost"]]},{"id":"ot-4-7","t":"I Send My Messenger","teach":["Malachi is the last book of the Old Testament. God promised to send a messenger to prepare the way before Him.","After 400 years of silence, John the Baptist appeared in the wilderness to prepare the way for Jesus."],"v":["Malachi 3:1"],"q":[["Who was the messenger Malachi promised?","John the Baptist","Elijah's servant","Ezra","Paul"],["Malachi is the ___ book of the Old Testament.","last","first","longest","middle"]]}]}]},{"id":"nt","name":"New Testament","color":"sapphire","desc":"Acts, the letters, and Revelation: how the early church lived, what the apostles taught, and how the story ends.","units":[{"t":"Acts","d":"The Holy Spirit and the first church.","lessons":[{"id":"nt-0-0","t":"You Will Be My Witnesses","teach":["Right before He ascended, Jesus told His followers they would receive power when the Holy Spirit came on them.","They would be His witnesses in Jerusalem, Judea, Samaria, and to the ends of the earth. The rest of Acts shows exactly that happening."],"v":["Acts 1:8"],"q":[["What would the disciples receive when the Spirit came?","Power","Gold","A kingdom","New names"],["How far would they be witnesses?","To the ends of the earth","Only in Jerusalem","Only in Israel","Only to their families"]]},{"id":"nt-0-1","t":"The First Church","teach":["After Pentecost, the new believers devoted themselves to four things.","The apostles' teaching, fellowship, the breaking of bread, and prayer. Those are still the heartbeat of a healthy church."],"v":["Acts 2:42"],"q":[["Which of these did the first church devote itself to?","Prayer","Politics","Building towers","Fasting only"],["Whose teaching did they follow?","The apostles'","The Pharisees'","The Romans'","The philosophers'"]]},{"id":"nt-0-2","t":"No Other Name","teach":["Peter and John were arrested for healing a man in Jesus' name. Standing before the rulers, Peter spoke boldly.","Salvation exists in no one else, for there is no other name under heaven given to men by which we must be saved."],"v":["Acts 4:12"],"q":[["By what name must we be saved?","Jesus","Moses","Abraham","Peter"],["Why were Peter and John arrested?","For healing in Jesus' name","For stealing","For starting a riot","For refusing taxes"]]},{"id":"nt-0-3","t":"Stephen's Faith","teach":["Stephen was the first Christian martyr, stoned for preaching Christ.","As he died, he prayed, \"Lord Jesus, receive my spirit,\" and \"Lord, do not hold this sin against them.\" He forgave just like Jesus did. A young man named Saul was watching."],"v":["Acts 7:59-60"],"q":[["Who was the first Christian martyr?","Stephen","James","Peter","Paul"],["What did Stephen pray for his killers?","Do not hold this sin against them","Punish them","Nothing","Strike them down"]]},{"id":"nt-0-4","t":"What Must I Do to Be Saved?","teach":["An earthquake shook open the prison where Paul and Silas were singing hymns at midnight. The jailer was terrified.","He asked, \"What must I do to be saved?\" They answered, \"Believe in the Lord Jesus, and you will be saved.\" He and his household were baptized that night."],"v":["Acts 16:30-31"],"q":[["Who asked \"What must I do to be saved?\"","The Philippian jailer","Pilate","Nicodemus","The rich young ruler"],["What was the answer?","Believe in the Lord Jesus","Keep the whole law","Give everything away","Go to Jerusalem"]]}]},{"t":"Romans and Galatians","d":"The heart of the gospel explained.","lessons":[{"id":"nt-1-0","t":"Peace with God","teach":["To be justified means to be declared righteous by God, like a judge declaring you not guilty.","Since we have been justified through faith, we have peace with God through our Lord Jesus Christ. The war is over."],"v":["Romans 5:1"],"q":[["Justified means God declares us...","Righteous","Rich","Perfect in behavior","Famous"],["Through whom do we have peace with God?","Our Lord Jesus Christ","Our good works","The priests","Moses"]]},{"id":"nt-1-1","t":"No Condemnation","teach":["Romans 7 ends with Paul's struggle against sin. Romans 8 opens with freedom.","There is now no condemnation for those who are in Christ Jesus. If you are in Christ, God's verdict over you is settled."],"v":["Romans 8:1"],"q":[["For whom is there no condemnation?","Those who are in Christ Jesus","Those who never sin","Everyone automatically","Only pastors"],["Which chapter of Romans begins with this verse?","Romans 8","Romans 1","Romans 12","Romans 3"]]},{"id":"nt-1-2","t":"Living Sacrifices","teach":["After eleven chapters on what God has done, Paul turns to how we respond.","Offer your bodies as living sacrifices. Do not be conformed to this world, but be transformed by the renewing of your mind."],"v":["Romans 12:1-2"],"q":[["How are we transformed?","By the renewing of our mind","By copying the world","By trying harder alone","By new clothes"],["What should we not be conformed to?","This world","God's will","The church","Scripture"]]},{"id":"nt-1-3","t":"Christ Lives in Me","teach":["Paul describes what happens in salvation: the old self died with Christ.","I have been crucified with Christ, and I no longer live, but Christ lives in me. I live by faith in the Son of God, who loved me and gave Himself up for me."],"v":["Galatians 2:20"],"q":[["Who lives in the believer, according to Galatians 2:20?","Christ","The law","An angel","Our old self"],["The Son of God loved me and gave ___ up for me.","Himself","His law","His throne","His temple"]]}]},{"t":"Corinthians","d":"Letters to a church learning to follow Jesus.","lessons":[{"id":"nt-2-0","t":"The Power of God","teach":["To the world, a crucified Savior sounds foolish.","But to us who are being saved, the message of the cross is the power of God."],"v":["1 Corinthians 1:18"],"q":[["To those being saved, the cross is...","The power of God","Foolishness","A legend","A defeat"],["To those perishing, the cross seems...","Foolishness","Powerful","Wise","Beautiful"]]},{"id":"nt-2-1","t":"You Are God's Temple","teach":["In the Old Testament, God's presence lived in the temple. Now the Holy Spirit lives in every believer.","Your body is a temple of the Holy Spirit. You were bought at a price, so glorify God with your body."],"v":["1 Corinthians 6:19-20"],"q":[["Who lives in the believer's body?","The Holy Spirit","An angel","The law","No one"],["You were bought at a ___.","price","market","temple","discount"]]},{"id":"nt-2-2","t":"Love Is Patient","teach":["Often read at weddings, this chapter shows what real love looks like.","Love is patient and kind. Faith, hope, and love remain, but the greatest of these is love."],"v":["1 Corinthians 13:4","1 Corinthians 13:13"],"q":[["What is the greatest of faith, hope, and love?","Love","Faith","Hope","They are all equal"],["Love is patient and ___.","kind","proud","quick","loud"]]},{"id":"nt-2-3","t":"A New Creation","teach":["When someone comes to Christ, God doesn't just improve the old life.","If anyone is in Christ, he is a new creation. The old has passed away, and the new has come."],"v":["2 Corinthians 5:17"],"q":[["If anyone is in Christ, he is a new ___.","creation","person on Sundays","rule-keeper","student"],["What happens to the old?","It has passed away","It gets stronger","It stays the same","It is hidden"]]},{"id":"nt-2-4","t":"My Grace Is Sufficient","teach":["Paul asked God three times to remove a painful \"thorn in the flesh.\"","God answered: My grace is sufficient for you, for My power is perfected in weakness. So Paul learned to boast in his weakness."],"v":["2 Corinthians 12:9"],"q":[["Where is God's power perfected?","In weakness","In strength","In wealth","In fame"],["How many times did Paul ask God to remove the thorn?","Three","Once","Seven","Forty"]]}]},{"t":"Letters from Prison","d":"Ephesians, Philippians, and Colossians.","lessons":[{"id":"nt-3-0","t":"His Workmanship","teach":["Right after saying we are saved by grace and not by works, Paul explains where good works fit.","We are God's workmanship, created in Christ Jesus to do good works that God prepared in advance for us."],"v":["Ephesians 2:10"],"q":[["We are God's ___.","workmanship","servants only","accident","reward"],["When did God prepare our good works?","In advance","After we earned them","Never","Only in heaven"]]},{"id":"nt-3-1","t":"Every Knee Will Bow","teach":["Jesus humbled Himself all the way to death on a cross. So God exalted Him to the highest place.","At the name of Jesus every knee will bow, and every tongue confess that Jesus Christ is Lord, to the glory of God the Father."],"v":["Philippians 2:10-11"],"q":[["At the name of Jesus, every ___ will bow.","knee","king","angel","head"],["What will every tongue confess?","Jesus Christ is Lord","Paul was right","God is angry","Rome is great"]]},{"id":"nt-3-2","t":"I Can Do All Things","teach":["Paul wrote this from prison. He had learned to be content whether full or hungry, with plenty or in need.","I can do all things through Christ who gives me strength. The secret is not circumstances but Christ."],"v":["Philippians 4:13"],"q":[["Where was Paul when he wrote Philippians?","In prison","In the temple","On a ship","In his home"],["Through whom can we do all things?","Christ","Ourselves","Our friends","The law"]]},{"id":"nt-3-3","t":"Things Above","teach":["Because we have been raised with Christ, our focus changes.","Set your minds on things above, not earthly things. Whatever you do, work at it with your whole being, for the Lord and not for men."],"v":["Colossians 3:2","Colossians 3:23"],"q":[["Where should we set our minds?","On things above","On earthly things","On our problems","On money"],["We should work at everything as working for ___.","the Lord","our boss only","ourselves","applause"]]}]},{"t":"Letters to Every Believer","d":"Thessalonians to Jude.","lessons":[{"id":"nt-4-0","t":"Rejoice, Pray, Give Thanks","teach":["Three short commands that shape every day.","Rejoice at all times, pray without ceasing, give thanks in every circumstance. This is God's will for you in Christ Jesus."],"v":["1 Thessalonians 5:16-18"],"q":[["How often should we pray?","Without ceasing","Once a week","Only in trouble","Only at meals"],["Giving thanks in every circumstance is God's ___ for you.","will","test","suggestion","punishment"]]},{"id":"nt-4-1","t":"Power, Love, and Self-Control","teach":["Timothy was a young pastor who sometimes struggled with timidity.","Paul reminded him: God has not given us a spirit of fear, but of power, love, and self-control."],"v":["2 Timothy 1:7"],"q":[["What spirit has God NOT given us?","Fear","Power","Love","Self-control"],["Who was Paul writing to?","Timothy","Titus","Peter","Philemon"]]},{"id":"nt-4-2","t":"I Have Kept the Faith","teach":["This is Paul's last letter, written shortly before he was executed for his faith.","He looked back without regret: I have fought the good fight, I have finished the race, I have kept the faith."],"v":["2 Timothy 4:7"],"q":[["What did Paul say he finished?","The race","The temple","His book","His journey to Spain"],["2 Timothy is Paul's ___ letter.","last","first","longest","only"]]},{"id":"nt-4-3","t":"The Same Forever","teach":["Hebrews shows Jesus is greater than angels, Moses, and the temple.","Fix your eyes on Jesus, the author and perfecter of our faith. Jesus Christ is the same yesterday and today and forever."],"v":["Hebrews 12:2","Hebrews 13:8"],"q":[["Jesus Christ is the same yesterday, today, and ___.","forever","tomorrow only","sometimes","in heaven only"],["Where should we fix our eyes?","On Jesus","On the finish line","On other runners","On ourselves"]]},{"id":"nt-4-4","t":"Doers of the Word","teach":["James was the brother of Jesus and a leader of the Jerusalem church.","He calls us to be doers of the word, not hearers only. Real faith always shows up in how we live."],"v":["James 1:22","James 2:17"],"q":[["We should be ___ of the word, not hearers only.","doers","readers","judges","teachers"],["Who was James?","The brother of Jesus","The son of Abraham","A Roman soldier","A prophet of Babylon"]]},{"id":"nt-4-5","t":"Cast Your Cares","teach":["Peter wrote to Christians facing hardship and persecution.","Cast all your anxiety on Him, because He cares for you. God isn't annoyed by your worries. He invites them."],"v":["1 Peter 5:7"],"q":[["What should we cast on God?","All our anxiety","Only big problems","Our money","Nothing"],["Why can we cast our cares on Him?","Because He cares for us","Because He is busy","Because we must earn it","Because the church said so"]]},{"id":"nt-4-6","t":"God Is Love","teach":["John, the disciple Jesus loved, wrote this letter as an old man.","God is love. We love because He first loved us. Our love is always a response to His."],"v":["1 John 4:8","1 John 4:19"],"q":[["Why do we love?","Because He first loved us","Because it feels good","To earn salvation","Because of the law"],["Complete it: \"God is ___.\"","love","far away","angry","silent"]]},{"id":"nt-4-7","t":"If We Confess","teach":["Christians still sin, and God provides the way back.","If we confess our sins, He is faithful and just to forgive us and to cleanse us from all unrighteousness."],"v":["1 John 1:9"],"q":[["What does God do when we confess our sins?","Forgives and cleanses us","Remembers them forever","Ignores us","Punishes us"],["God is faithful and ___ to forgive.","just","slow","unsure","tired"]]}]},{"t":"Revelation","d":"Jesus revealed in glory and the victory to come.","lessons":[{"id":"nt-5-0","t":"Alpha and Omega","teach":["The apostle John was exiled on the island of Patmos when the risen Jesus appeared to him in glory.","The Lord God declares: I am the Alpha and the Omega, who is and was and is to come, the Almighty."],"v":["Revelation 1:8"],"q":[["Where was John when he received Revelation?","The island of Patmos","Rome","Jerusalem","Ephesus' prison"],["Which title does Revelation 1:8 use?","The Almighty","The Prophet","The Teacher","The Rabbi"]]},{"id":"nt-5-1","t":"I Stand at the Door","teach":["Jesus wrote to seven churches. To a lukewarm church in Laodicea, He gave a tender invitation.","Behold, I stand at the door and knock. If anyone hears My voice and opens the door, I will come in and dine with him."],"v":["Revelation 3:20"],"q":[["What is Jesus doing at the door?","Knocking","Locking it","Waiting silently","Walking away"],["What will Jesus do if someone opens the door?","Come in and dine with them","Judge them","Leave","Send an angel"]]},{"id":"nt-5-2","t":"Worthy Is the Lamb","teach":["In heaven, no one was found worthy to open God's scroll until the Lamb who was slain stepped forward.","Thousands upon thousands of angels sang: Worthy is the Lamb who was slain, to receive power and riches and wisdom and strength and honor and glory and blessing!"],"v":["Revelation 5:12"],"q":[["Who alone was worthy to open the scroll?","The Lamb who was slain","John","An angel","Moses"],["Who sang \"Worthy is the Lamb\"?","Thousands upon thousands of angels","Only John","The Pharisees","No one"]]},{"id":"nt-5-3","t":"King of Kings","teach":["John saw heaven opened and Jesus riding out on a white horse to defeat evil once and for all.","On His robe and thigh He has a name written: KING OF KINGS AND LORD OF LORDS."],"v":["Revelation 19:16"],"q":[["What name is written on Jesus' robe?","King of Kings and Lord of Lords","Son of Man","The Good Shepherd","Rabbi"],["What was Jesus riding in John's vision?","A white horse","A donkey","A chariot","A cloud of fire"]]}]}]},{"id":"gospels","name":"The Gospels","color":"emerald","desc":"Matthew, Mark, Luke, and John: the life, teaching, miracles, death, and resurrection of Jesus, in order.","units":[{"t":"The Savior Is Born","d":"The birth and childhood of Jesus.","lessons":[{"id":"gospels-0-0","t":"No Word from God Will Fail","teach":["The angel Gabriel appeared to Mary, a virgin engaged to Joseph, and told her she would give birth to the Son of God.","Mary wondered how. Gabriel answered that the Holy Spirit would come upon her, for no word from God will ever fail."],"v":["Luke 1:31","Luke 1:37"],"q":[["Which angel visited Mary?","Gabriel","Michael","Raphael","An unnamed angel"],["What name was Mary told to give her son?","Jesus","Immanuel","John","David"]]},{"id":"gospels-0-1","t":"Good News of Great Joy","teach":["Jesus was born in Bethlehem and laid in a manger because there was no room at the inn.","Angels appeared to shepherds in the fields: I bring you good news of great joy. Today in the city of David a Savior has been born to you. He is Christ the Lord."],"v":["Luke 2:10-11"],"q":[["Who did the angels announce Jesus' birth to first?","Shepherds","Kings","Priests","Romans"],["Where was baby Jesus laid?","In a manger","In a palace","In the temple","In a boat"]]},{"id":"gospels-0-2","t":"The Magi Worship","teach":["Wise men from the east followed a star to find the newborn King of the Jews.","When they found Jesus, they bowed down and worshiped Him and gave gifts of gold, frankincense, and myrrh."],"v":["Matthew 2:1-2","Matthew 2:11"],"q":[["What led the Magi to Jesus?","A star","An angel","A map","King Herod's soldiers"],["Which was one of their gifts?","Myrrh","Silver","Wine","Bread"]]},{"id":"gospels-0-3","t":"My Father's House","teach":["At twelve years old, Jesus stayed behind at the temple in Jerusalem, amazing the teachers with His understanding.","When Mary and Joseph found Him, He said, \"Did you not know that I had to be in My Father's house?\" Jesus grew in wisdom and stature, and in favor with God and man."],"v":["Luke 2:49","Luke 2:52"],"q":[["How old was Jesus when He stayed at the temple?","Twelve","Thirty","Seven","Eighteen"],["Whose house did Jesus call the temple?","His Father's","Herod's","Moses'","The priests'"]]}]},{"t":"The Ministry Begins","d":"Baptism, temptation, and the first disciples.","lessons":[{"id":"gospels-1-0","t":"This Is My Beloved Son","teach":["Jesus was baptized by John in the Jordan River.","The heavens opened, the Spirit descended like a dove, and the Father's voice said, \"This is My beloved Son, in whom I am well pleased.\" Father, Son, and Spirit all present at once."],"v":["Matthew 3:16-17"],"q":[["Who baptized Jesus?","John the Baptist","Peter","Andrew","Nicodemus"],["How did the Spirit descend?","Like a dove","Like fire","Like wind","Like rain"]]},{"id":"gospels-1-1","t":"It Is Written","teach":["After fasting forty days in the wilderness, Jesus was tempted by the devil.","Every time, Jesus answered with Scripture: \"It is written: Man shall not live on bread alone, but on every word that comes from the mouth of God.\""],"v":["Matthew 4:4"],"q":[["How did Jesus answer each temptation?","With Scripture","With silence","With a miracle","By running away"],["How long did Jesus fast in the wilderness?","Forty days","Seven days","Three days","Twelve days"]]},{"id":"gospels-1-2","t":"Fishers of Men","teach":["Walking by the Sea of Galilee, Jesus saw two brothers, Peter and Andrew, casting nets.","He said, \"Come, follow Me, and I will make you fishers of men.\" At once they left their nets and followed Him."],"v":["Matthew 4:19-20"],"q":[["What were Peter and Andrew doing?","Fishing","Farming","Collecting taxes","Building"],["How quickly did they follow Jesus?","At once","After a year","After asking their father","They refused at first"]]},{"id":"gospels-1-3","t":"The First Sign","teach":["At a wedding in Cana, the wine ran out. Jesus had servants fill jars with water, and it became the best wine.","This was the first of His signs. It revealed His glory, and His disciples believed in Him."],"v":["John 2:11"],"q":[["Where did Jesus turn water into wine?","Cana","Bethlehem","Jerusalem","Nazareth"],["What did this first sign reveal?","His glory","His weakness","His family","His age"]]}]},{"t":"The Sermon on the Mount","d":"Jesus' most famous teaching, Matthew 5 to 7.","lessons":[{"id":"gospels-2-0","t":"Blessed Are","teach":["Jesus began His great sermon with the Beatitudes, blessings that turn the world's values upside down.","Blessed are the poor in spirit, for theirs is the kingdom of heaven. Blessed are the pure in heart, for they will see God."],"v":["Matthew 5:3","Matthew 5:8"],"q":[["What do the pure in heart receive?","They will see God","Riches","The earth","Long life"],["These blessings are called the ___.","Beatitudes","Proverbs","Psalms","Commandments"]]},{"id":"gospels-2-1","t":"Salt and Light","teach":["Jesus told His followers who they are: the light of the world, a city on a hill that cannot be hidden.","Let your light shine before men, so they may see your good deeds and glorify your Father in heaven."],"v":["Matthew 5:14","Matthew 5:16"],"q":[["Jesus said His followers are the light of the ___.","world","temple","nation","night"],["Who gets the glory for our good deeds?","Our Father in heaven","Ourselves","Our church","Our parents"]]},{"id":"gospels-2-2","t":"The Lord's Prayer","teach":["When His disciples asked how to pray, Jesus gave them a model.","It starts with God: Our Father in heaven, hallowed be Your name. Then it brings our needs: give us this day our daily bread."],"v":["Matthew 6:9-11"],"q":[["How does the Lord's Prayer begin?","Our Father in heaven","Dear Lord Jesus","Almighty King","God of Abraham"],["What do we ask for daily?","Our daily bread","Riches","Victory","A sign"]]},{"id":"gospels-2-3","t":"Seek First","teach":["Jesus told His followers not to worry about food or clothes. The Father feeds the birds and clothes the lilies.","Seek first the kingdom of God and His righteousness, and all these things will be added to you."],"v":["Matthew 6:33-34"],"q":[["What should we seek first?","God's kingdom and righteousness","Food","Money","Comfort"],["What will be added to us?","All these things we need","Nothing","Only trouble","A crown"]]},{"id":"gospels-2-4","t":"Ask, Seek, Knock","teach":["Jesus invites us to pray with confidence.","Ask and it will be given to you; seek and you will find; knock and the door will be opened to you. The Father loves to give good gifts to His children."],"v":["Matthew 7:7"],"q":[["What happens when we knock?","The door will be opened","Nothing","We wait forever","We are turned away"],["Jesus compares God to a ___ who gives good gifts.","Father","King","Judge","Master"]]},{"id":"gospels-2-5","t":"The Wise Builder","teach":["Jesus summed up the Law and the Prophets in the Golden Rule: do to others what you would have them do to you.","He ended the sermon with a picture: whoever hears His words and does them is like a wise man who built his house on the rock."],"v":["Matthew 7:12","Matthew 7:24"],"q":[["Where did the wise man build his house?","On the rock","On the sand","On a hill","By the sea"],["What is the Golden Rule?","Do to others what you would have them do to you","Love your enemies only","An eye for an eye","Pray every day"]]}]},{"t":"Miracles and Signs","d":"Jesus' power over nature, sickness, and death.","lessons":[{"id":"gospels-3-0","t":"Even the Wind Obeys","teach":["A furious storm hit the boat while Jesus slept. The terrified disciples woke Him.","Jesus rebuked the wind and the sea: \"Silence! Be still!\" And it was perfectly calm. The disciples asked, \"Who is this, that even the wind and the sea obey Him?\""],"v":["Mark 4:39","Mark 4:41"],"q":[["What was Jesus doing during the storm?","Sleeping","Praying","Fishing","Rowing"],["What obeyed Jesus?","The wind and the sea","Only the disciples","Only the wind","The Romans"]]},{"id":"gospels-3-1","t":"The Bread of Life","teach":["With five barley loaves and two fish from a boy's lunch, Jesus fed about five thousand men.","The next day He explained the sign: \"I am the bread of life. Whoever comes to Me will never hunger.\""],"v":["John 6:11","John 6:35"],"q":[["How many loaves were there?","Five","Two","Seven","Twelve"],["Jesus said, \"I am the bread of ___.\"","life","heaven","Israel","peace"]]},{"id":"gospels-3-2","t":"Take Courage","teach":["Jesus came to His disciples walking on the water. He said, \"Take courage! It is I. Do not be afraid.\"","Peter walked on the water too, until he looked at the wind and began to sink. Jesus immediately reached out and caught him."],"v":["Matthew 14:27","Matthew 14:31"],"q":[["Who walked on the water with Jesus?","Peter","John","Thomas","Andrew"],["Why did Peter begin to sink?","He saw the wind and was afraid","He was too heavy","Jesus let go","The boat pulled him"]]},{"id":"gospels-3-3","t":"I Was Blind, Now I See","teach":["Jesus healed a man who had been born blind. The religious leaders questioned him again and again.","The man gave a simple, powerful testimony: \"One thing I do know: I was blind, but now I see!\""],"v":["John 9:25"],"q":[["How long had the man been blind?","Since birth","One year","Since a battle","A week"],["What was the man's simple testimony?","I was blind, but now I see","I don't know Him","Ask my parents","It was a trick"]]},{"id":"gospels-3-4","t":"Lazarus, Come Out","teach":["Lazarus, Jesus' friend, had been dead four days when Jesus arrived. Jesus wept with the grieving family.","Then He shouted, \"Lazarus, come out!\" and the dead man walked out of the tomb. Jesus has power over death itself."],"v":["John 11:35","John 11:43"],"q":[["How long had Lazarus been dead?","Four days","Three days","One day","A week"],["What did Jesus do before raising Lazarus?","He wept","He left","He slept","He rebuked Martha"]]}]},{"t":"Parables","d":"Stories Jesus told about the kingdom of God.","lessons":[{"id":"gospels-4-0","t":"The Lost Sheep","teach":["A shepherd with a hundred sheep loses one. He leaves the ninety-nine and searches until he finds it.","Jesus said there is more joy in heaven over one sinner who repents than over ninety-nine who need no repentance."],"v":["Luke 15:4","Luke 15:7"],"q":[["How many sheep did the shepherd leave to find the lost one?","Ninety-nine","Ten","Fifty","One hundred"],["What causes joy in heaven?","One sinner who repents","A big offering","A new temple","A perfect life"]]},{"id":"gospels-4-1","t":"The Prodigal Son","teach":["A son took his inheritance early and wasted it all. Starving, he came home hoping to be a servant.","While he was still far away, his father saw him, ran to him, and kissed him. That is how the Father welcomes anyone who comes home."],"v":["Luke 15:20","Luke 15:24"],"q":[["What did the father do when he saw his son?","Ran to him and kissed him","Turned him away","Made him a servant","Waited inside"],["The father said his son was dead and is ___.","alive again","forgotten","punished","a servant"]]},{"id":"gospels-4-2","t":"The Good Samaritan","teach":["An expert in the law asked, \"Who is my neighbor?\" Jesus told of a man beaten and left on the road. A priest and a Levite passed by.","A Samaritan, an outsider, stopped and cared for him. Jesus said, \"Go and do likewise.\""],"v":["Luke 10:27","Luke 10:37"],"q":[["Who helped the beaten man?","A Samaritan","A priest","A Levite","A Roman soldier"],["What did Jesus tell the man to do?","Go and do likewise","Stay away from Samaritans","Pray about it","Ask the priest"]]},{"id":"gospels-4-3","t":"The Sower","teach":["A farmer scattered seed. Some fell on the path, rocky ground, and among thorns, and did not last.","The seed on good soil is the one who hears the word and understands it. He bears fruit, a hundred, sixty, or thirty times what was sown."],"v":["Matthew 13:23"],"q":[["What does the seed stand for?","God's word","Money","Children","Rain"],["What does the good soil produce?","Much fruit","Thorns","Nothing","Rocks"]]}]},{"t":"Who Is Jesus?","d":"Peter's confession and the \"I am\" sayings.","lessons":[{"id":"gospels-5-0","t":"You Are the Christ","teach":["Jesus asked His disciples, \"Who do you say I am?\"","Peter answered, \"You are the Christ, the Son of the living God.\" Jesus said this truth was revealed to him by the Father."],"v":["Matthew 16:15-16"],"q":[["Who answered Jesus' question?","Peter","John","Judas","Thomas"],["What did Peter call Jesus?","The Christ, the Son of the living God","A good teacher","Elijah","John the Baptist"]]},{"id":"gospels-5-1","t":"The Good Shepherd","teach":["Jesus is the Good Shepherd who lays down His life for the sheep.","He gives His sheep eternal life, they will never perish, and no one can snatch them out of His hand."],"v":["John 10:11","John 10:28"],"q":[["What does the Good Shepherd do for the sheep?","Lays down His life","Sells them","Leaves them","Counts them"],["Can anyone snatch Jesus' sheep from His hand?","No one","Only the devil","Only wolves","Anyone strong enough"]]},{"id":"gospels-5-2","t":"The Light of the World","teach":["During a festival lit by giant lamps in the temple courts, Jesus stood and made a bold claim.","\"I am the light of the world. Whoever follows Me will never walk in the darkness, but will have the light of life.\""],"v":["John 8:12"],"q":[["Whoever follows Jesus will never walk in ___.","darkness","the desert","fear","the rain"],["Jesus said, \"I am the light of the ___.\"","world","temple","morning","church"]]},{"id":"gospels-5-3","t":"The True Vine","teach":["On His last night, Jesus taught His disciples how to stay close to Him.","I am the vine; you are the branches. Whoever remains in Me will bear much fruit, for apart from Me you can do nothing."],"v":["John 15:5"],"q":[["In John 15, who are the branches?","Us, His followers","The angels","The Pharisees","The prophets"],["What can we do apart from Jesus?","Nothing","Most things","Everything","Only small things"]]},{"id":"gospels-5-4","t":"Before Abraham Was, I Am","teach":["The religious leaders argued with Jesus about Abraham, who lived about 2,000 years earlier.","Jesus answered, \"Before Abraham was born, I am!\" He used God's own name from the burning bush. They picked up stones, because they knew He was claiming to be God."],"v":["John 8:58"],"q":[["Whose name from the burning bush did Jesus use?","God's name, I AM","Moses' name","Abraham's name","Elijah's name"],["Why did the leaders pick up stones?","Jesus was claiming to be God","He insulted Abraham","He broke the Sabbath","He refused to pay taxes"]]}]},{"t":"The Final Week","d":"From Palm Sunday to the empty tomb.","lessons":[{"id":"gospels-6-0","t":"Hosanna!","teach":["Jesus rode into Jerusalem on a donkey as crowds spread cloaks and branches on the road.","They shouted, \"Hosanna to the Son of David! Blessed is He who comes in the name of the Lord!\" We remember this on Palm Sunday."],"v":["Matthew 21:9"],"q":[["What did the crowds shout?","Hosanna","Crucify Him","Long live Caesar","Amen"],["What did Jesus ride into Jerusalem?","A donkey","A horse","A chariot","A camel"]]},{"id":"gospels-6-1","t":"A New Commandment","teach":["Jesus washed His disciples' feet, doing a servant's job, then gave them a new command.","Love one another as I have loved you. By this everyone will know you are My disciples."],"v":["John 13:34-35"],"q":[["How will people know we are Jesus' disciples?","By our love for one another","By our clothes","By our knowledge","By our size"],["What servant's job did Jesus do that night?","Washed His disciples' feet","Cooked the meal","Carried water","Swept the room"]]},{"id":"gospels-6-2","t":"Not My Will","teach":["In the garden of Gethsemane, Jesus prayed with such anguish that His sweat was like drops of blood.","\"Father, if You are willing, take this cup from Me. Yet not My will, but Yours be done.\" Then He went willingly to the cross."],"v":["Luke 22:42"],"q":[["Where did Jesus pray this prayer?","Gethsemane","The temple","Golgotha","Bethany"],["Jesus prayed, \"Not My will, but ___.\"","Yours be done","Mine be done","theirs be done","it is finished"]]},{"id":"gospels-6-3","t":"Father, Forgive Them","teach":["On the cross, Jesus prayed for the very people crucifying Him: \"Father, forgive them, for they do not know what they are doing.\"","A criminal beside Him believed. Jesus promised, \"Today you will be with Me in Paradise.\""],"v":["Luke 23:34","Luke 23:43"],"q":[["Who did Jesus pray for on the cross?","Those crucifying Him","Only His mother","Only His disciples","No one"],["What did Jesus promise the believing criminal?","Today you will be with Me in Paradise","You will be set free","You will be judged","Nothing"]]},{"id":"gospels-6-4","t":"Why Look for the Living Among the Dead?","teach":["Early on Sunday, women brought spices to the tomb and found the stone rolled away.","Two men in dazzling clothes said, \"Why do you look for the living among the dead? He is not here; He has risen!\""],"v":["Luke 24:5-6"],"q":[["Who first found the empty tomb?","Women who brought spices","Pilate","The Pharisees","Roman soldiers"],["What was rolled away from the tomb?","The stone","The door","The guards","The cloth"]]},{"id":"gospels-6-5","t":"Our Hearts Burned","teach":["Two disciples walked to Emmaus, sad and confused. The risen Jesus walked with them, though they didn't recognize Him.","Beginning with Moses and all the Prophets, He explained what the Scriptures said about Himself. Later they said, \"Were not our hearts burning within us?\""],"v":["Luke 24:27","Luke 24:32"],"q":[["Where were the two disciples walking?","Emmaus","Bethlehem","Damascus","Jericho"],["What did Jesus explain to them?","What the Scriptures said about Himself","How to fish","Roman law","Where to hide"]]}]}]},{"id":"stories","name":"Famous Stories","color":"amethyst","desc":"The stories everyone should know, from Noah's ark to Paul's shipwreck, and what each one shows us about God.","units":[{"t":"In the Beginning","d":"The first stories of the Bible.","lessons":[{"id":"stories-0-0","t":"Adam and Eve","teach":["God formed the first man from the dust and breathed life into him. He placed Adam and Eve in the garden of Eden.","After they sinned, they hid. But God came looking for them, calling, \"Where are you?\" God has been seeking lost people ever since."],"v":["Genesis 2:7","Genesis 3:9"],"q":[["What did God form Adam from?","The dust of the ground","A rib","Water","Clay from a river"],["What did God call out after Adam and Eve sinned?","Where are you?","What have you done?","Leave the garden!","Who told you?"]]},{"id":"stories-0-1","t":"Cain and Abel","teach":["Adam and Eve's sons brought offerings to God. God accepted Abel's, and Cain grew jealous and angry.","Cain killed his brother. When God asked where Abel was, Cain answered, \"Am I my brother's keeper?\" Sin, left unchecked, grows."],"v":["Genesis 4:9"],"q":[["Who killed Abel?","Cain, his brother","Adam","Seth","A wild animal"],["What did Cain ask God?","Am I my brother's keeper?","Why me?","Where is Abel?","Can I be forgiven?"]]},{"id":"stories-0-2","t":"Noah's Ark","teach":["God told Noah to build a huge ark and bring his family and the animals inside. Noah did everything exactly as God commanded.","The flood covered the earth, but God remembered Noah and everyone in the ark, and the waters went down. God keeps those who trust Him."],"v":["Genesis 6:22","Genesis 8:1"],"q":[["How much of God's command did Noah follow?","Everything, exactly as commanded","Most of it","Only the measurements","He argued first"],["What did God do for Noah during the flood?","Remembered him","Forgot him","Sent him away","Made him king"]]},{"id":"stories-0-3","t":"The Tower of Babel","teach":["People united to build a tower reaching to the heavens, to make a name for themselves.","God confused their language and scattered them over the earth. The place was called Babel. Pride that tries to reach God without Him always falls."],"v":["Genesis 11:4","Genesis 11:9"],"q":[["Why did the people build the tower?","To make a name for themselves","To worship God","To escape a flood","To store grain"],["What did God do to the builders?","Confused their language","Sent fire","Made them kings","Nothing"]]}]},{"t":"The Patriarchs","d":"Abraham, Isaac, Jacob, and Joseph.","lessons":[{"id":"stories-1-0","t":"Abraham and Isaac","teach":["God told Abraham to take his only son Isaac, whom he loved, to Mount Moriah and offer him.","Abraham obeyed, and at the last moment the angel of the LORD stopped him: \"Now I know that you fear God.\" Centuries later, God gave His own only Son on a hill in that same region."],"v":["Genesis 22:2","Genesis 22:12"],"q":[["Where did Abraham take Isaac?","Mount Moriah","Mount Sinai","Mount Carmel","Mount Ararat"],["Who stopped Abraham?","The angel of the LORD","Isaac","Sarah","A servant"]]},{"id":"stories-1-1","t":"Jacob's Ladder","teach":["Running from his angry brother Esau, Jacob slept on the ground with a stone for a pillow.","He dreamed of a ladder reaching to heaven with angels going up and down, and God promised, \"I am with you and will watch over you wherever you go.\""],"v":["Genesis 28:12","Genesis 28:15"],"q":[["What did Jacob see in his dream?","A ladder to heaven with angels","A burning bush","Seven cows","A great flood"],["Who was Jacob running from?","His brother Esau","Pharaoh","Laban","The Philistines"]]},{"id":"stories-1-2","t":"Joseph's Coat","teach":["Jacob loved Joseph more than his other sons and made him a robe of many colors.","His jealous brothers sold him to traders for twenty shekels of silver, and he was taken to Egypt. But God was with Joseph every step."],"v":["Genesis 37:3","Genesis 37:28"],"q":[["What did Jacob make for Joseph?","A robe of many colors","A sword","A ring","A sheepfold"],["Where was Joseph taken?","Egypt","Babylon","Canaan","Assyria"]]},{"id":"stories-1-3","t":"Joseph Forgives","teach":["Years later, Joseph's brothers came to Egypt to buy food and bowed before him, not knowing who he was.","Joseph revealed himself: \"I am Joseph, your brother.\" Instead of revenge, he told them God sent him ahead to preserve life."],"v":["Genesis 45:4-5"],"q":[["Why did the brothers come to Egypt?","To buy food in a famine","To find Joseph","To trade sheep","To escape war"],["What did Joseph choose instead of revenge?","Forgiveness","Prison for them","Slavery for them","To send them away"]]}]},{"t":"Exodus and Conquest","d":"Moses, the Red Sea, and the promised land.","lessons":[{"id":"stories-2-0","t":"Baby Moses","teach":["Pharaoh ordered every Hebrew baby boy thrown into the Nile. Moses' mother hid him in a basket among the reeds.","Pharaoh's own daughter found him and raised him as her son. She named him Moses, because she drew him out of the water."],"v":["Exodus 2:10"],"q":[["Where was baby Moses hidden?","In a basket on the Nile","In a cave","In the temple","In a barn"],["Who raised Moses?","Pharaoh's daughter","His sister Miriam","A priest","Joseph"]]},{"id":"stories-2-1","t":"The Burning Bush","teach":["Moses was tending sheep when he saw a bush on fire that did not burn up.","God called to him from the bush: take off your sandals, for the place where you are standing is holy ground."],"v":["Exodus 3:2","Exodus 3:5"],"q":[["What was strange about the burning bush?","It did not burn up","It was blue","It sang","It moved"],["Why did Moses take off his sandals?","He stood on holy ground","They were wet","It was hot","He was tired"]]},{"id":"stories-2-2","t":"Parting the Red Sea","teach":["Moses stretched out his hand over the sea, and the LORD drove it back with a strong east wind all night.","The Israelites walked through on dry ground, with walls of water on their right and left."],"v":["Exodus 14:21-22"],"q":[["What drove the sea back?","A strong east wind from the LORD","An earthquake","The sun","Moses' strength"],["How did the Israelites cross?","On dry ground","Through mud","By swimming","On boats"]]},{"id":"stories-2-3","t":"Bread from Heaven","teach":["In the wilderness the people grumbled about food.","God rained bread from heaven every morning, called manna. They gathered just enough for each day, learning to trust God daily."],"v":["Exodus 16:4"],"q":[["What was the bread from heaven called?","Manna","Matzah","Showbread","Quail"],["How often did they gather it?","Each day","Once a week","Once a month","Only on the Sabbath"]]},{"id":"stories-2-4","t":"The Walls of Jericho","teach":["God told Joshua to march around Jericho once a day for six days, and seven times on the seventh.","When the rams' horns sounded and the people shouted, the wall collapsed. Victory came by obeying God, not by force."],"v":["Joshua 6:20"],"q":[["How many times did they march on the seventh day?","Seven","Once","Twelve","Forty"],["What made the walls fall?","God, as they obeyed and shouted","Battering rams","An earthquake they caused","Fire"]]},{"id":"stories-2-5","t":"Gideon's Three Hundred","teach":["Gideon was hiding from his enemies when the angel of the LORD greeted him: \"The LORD is with you, mighty man of valor.\"","God cut Gideon's army from 32,000 to just 300 so Israel would know the victory was God's."],"v":["Judges 6:12","Judges 7:7"],"q":[["How many men did Gideon fight with?","300","32,000","10,000","12"],["Why did God make the army so small?","So Israel would know the victory was God's","There was no food","The rest were sick","To trick Gideon"]]}]},{"t":"Heroes of Israel","d":"Faith, courage, and God's power.","lessons":[{"id":"stories-3-0","t":"Samson's Last Prayer","teach":["Samson's strength came from God, but he gave away his secret to Delilah, lost his strength, and was captured and blinded.","In his final moment he prayed, \"Remember me, O Lord GOD. Strengthen me just once more,\" and God answered."],"v":["Judges 16:28"],"q":[["Who betrayed Samson's secret?","Delilah","Ruth","Jezebel","Esther"],["What did Samson ask God for in the end?","Strength just once more","Escape","His eyesight","A new army"]]},{"id":"stories-3-1","t":"David and Goliath","teach":["The giant Goliath mocked Israel's army for forty days. Young David volunteered with only a sling and five stones.","David said, \"You come against me with sword and spear, but I come against you in the name of the LORD of Hosts. The battle is the LORD's.\""],"v":["1 Samuel 17:45","1 Samuel 17:47"],"q":[["What did David bring against Goliath?","A sling and stones","A sword and shield","A spear","An army"],["Whose battle did David say it was?","The LORD's","Saul's","His own","Israel's army's"]]},{"id":"stories-3-2","t":"Fire on Mount Carmel","teach":["Elijah challenged 450 prophets of Baal: the God who answers by fire is God. Baal's prophets shouted all day with no answer.","Elijah soaked his altar with water and prayed once. The fire of the LORD fell and burned it all, and the people cried, \"The LORD, He is God!\""],"v":["1 Kings 18:38-39"],"q":[["How many prophets of Baal did Elijah face?","450","12","100","1,000"],["What did the people cry out?","The LORD, He is God!","Baal is god!","Elijah is king!","We are afraid!"]]},{"id":"stories-3-3","t":"The Chariot of Fire","teach":["Elijah never died. As he walked with Elisha, a chariot of fire and horses of fire appeared.","Elijah went up to heaven in a whirlwind, and Elisha carried on his ministry with a double portion of his spirit."],"v":["2 Kings 2:11"],"q":[["How did Elijah go to heaven?","In a whirlwind with a chariot of fire","He died of old age","He climbed a mountain","On a cloud"],["Who continued Elijah's ministry?","Elisha","Samuel","Jonah","Isaiah"]]},{"id":"stories-3-4","t":"Naaman Is Healed","teach":["Naaman was a powerful army commander with leprosy. Elisha told him to wash seven times in the Jordan River.","Naaman was offended at first, but when he humbled himself and obeyed, his skin became like a little child's. He was clean."],"v":["2 Kings 5:14"],"q":[["How many times did Naaman wash in the Jordan?","Seven","Once","Three","Twelve"],["What disease did Naaman have?","Leprosy","Blindness","Fever","Paralysis"]]}]},{"t":"Faith Under Fire","d":"God's people standing firm.","lessons":[{"id":"stories-4-0","t":"The Fiery Furnace","teach":["Shadrach, Meshach, and Abednego refused to bow to King Nebuchadnezzar's golden statue.","They told the king that even if God did not rescue them, they would never bow. The king threw them into the blazing furnace, then saw four men walking in the fire, unharmed. God was with them in the flames, and not a hair was singed."],"v":["Daniel 3:18","Daniel 3:25"],"q":[["What did the three friends refuse to do?","Bow to the golden statue","Eat the king's food","Pray to God","Leave Babylon"],["Which king threw them in the furnace?","Nebuchadnezzar","Darius","Pharaoh","Herod"]]},{"id":"stories-4-1","t":"The Lions' Den","teach":["A law said no one could pray to anyone but the king. Daniel went home and prayed to God three times a day, just as before.","He was thrown to the lions, but God sent His angel and shut the lions' mouths."],"v":["Daniel 6:10","Daniel 6:22"],"q":[["How often did Daniel pray?","Three times a day","Once a week","Only in secret on holidays","Once a year"],["Who shut the lions' mouths?","God's angel","The king","Daniel","A soldier"]]},{"id":"stories-4-2","t":"Jonah and the Great Fish","teach":["Jonah fled from God's call to preach to Nineveh. God appointed a great fish to swallow him, and he was inside three days and three nights.","When Jonah finally preached, the whole city repented, and God showed them mercy."],"v":["Jonah 1:17","Jonah 3:10"],"q":[["How long was Jonah inside the fish?","Three days and three nights","Forty days","One night","A week"],["What happened when Nineveh repented?","God showed mercy","God destroyed it","Jonah was punished","Nothing changed"]]},{"id":"stories-4-3","t":"If I Perish, I Perish","teach":["Going to the king without being summoned could mean death. Esther asked all the Jews to fast for her for three days.","Then she said, \"I will go to the king, even though it is against the law. And if I perish, I perish.\" God used her courage to save her people."],"v":["Esther 4:16"],"q":[["What did Esther ask the Jews to do?","Fast for three days","Fight","Run away","Write to the king"],["What did Esther say about the risk?","If I perish, I perish","I will wait","Someone else should go","The king will understand"]]},{"id":"stories-4-4","t":"Job's Faith","teach":["When Job lost everything in one day, he fell to the ground and worshiped: \"The LORD gave, and the LORD has taken away. Blessed be the name of the LORD.\"","At the end, God restored Job's fortunes and gave him twice as much as before."],"v":["Job 1:21","Job 42:10"],"q":[["What did Job do when he lost everything?","Worshiped God","Cursed God","Ran away","Blamed his friends forever"],["How much did God restore to Job?","Twice as much as before","Nothing","Half","Exactly the same"]]}]},{"t":"Lives Changed by Jesus","d":"Real people who met Jesus.","lessons":[{"id":"stories-5-0","t":"Zacchaeus","teach":["Zacchaeus was a rich, hated tax collector, too short to see Jesus over the crowd, so he climbed a sycamore tree.","Jesus stopped, called him by name, and went to his house. Zacchaeus' life was changed. The Son of Man came to seek and to save the lost."],"v":["Luke 19:5","Luke 19:10"],"q":[["What did Zacchaeus climb?","A sycamore tree","A wall","A roof","A mountain"],["Why did Jesus come, according to Luke 19:10?","To seek and to save the lost","To start a kingdom on earth","To judge Rome","To rebuild the temple"]]},{"id":"stories-5-1","t":"The Woman at the Well","teach":["Jesus spoke with a Samaritan woman at a well at noon, something Jewish teachers never did.","He offered her living water: whoever drinks the water I give will never thirst. She ran to tell her whole town about Him."],"v":["John 4:14"],"q":[["What did Jesus offer the woman?","Living water","Money","A new husband","Food"],["What did she do after meeting Jesus?","Told her whole town about Him","Hid","Went back to the well","Left Samaria"]]},{"id":"stories-5-2","t":"Peter Restored","teach":["Peter denied knowing Jesus three times, then the Lord turned and looked at him, and Peter wept bitterly.","After the resurrection, Jesus asked Peter three times, \"Do you love Me?\" and three times restored him: \"Feed My sheep.\""],"v":["Luke 22:61-62","John 21:17"],"q":[["How many times did Peter deny Jesus?","Three","Once","Two","Seven"],["What did Jesus tell Peter after restoring him?","Feed My sheep","Go home","Never fail again","Build a church building"]]},{"id":"stories-5-3","t":"Midnight in Prison","teach":["Paul and Silas were beaten and locked in stocks in Philippi. At midnight they were praying and singing hymns, and the prisoners were listening.","Suddenly an earthquake shook the prison, every door flew open, and every chain came loose."],"v":["Acts 16:25-26"],"q":[["What were Paul and Silas doing at midnight?","Praying and singing hymns","Sleeping","Planning an escape","Complaining"],["What happened next?","An earthquake opened the doors","A guard let them out","They were executed","Nothing"]]}]}]}];
